  if (newDay) p.expire(K.series(day), 60 * 60 * 24 * 8);
  if (live.solarWhLifetime != null && live.dayBaseSolarWh != null) p.hset(K.daily, { [day]: Math.round(live.solarWhLifetime - live.dayBaseSolarWh) });
